module multi_pipe_4bit (
	input wire clk,
	input wire rst_n,
	input wire [3:0] mul_a,
	input wire [3:0] mul_b,
	output wire [7:0] mul_out
);
	// Parameter for the size of the multiplier
	parameter size = 4;

	// Extended multiplicand
	wire [7:0] a_ext = {{size{1'd0}}, mul_a};
	// Extended multiplier
	wire [7:0] b_ext = {{size{1'd0}}, mul_b};

	reg [7:0] partial_products[size-1:0];
	genvar i;
	generate
	    for(i = 0; i < size; i=i+1) begin: gen_partial_products
	        assign partial_products[i] = (b_ext[i] == 1'd1) ? (a_ext << i) : 'd0;
	    end
	endgenerate

	// Pipeline Registers for Stages
	reg [7:0] sum_tmp1, sum_tmp2;

	// Adder logic for stage 1
	always @(*) begin
	    if(!rst_n) begin
	        sum_tmp1 = 'd0;
	        sum_tmp2 = 'd0;
	    end else begin
	        sum_tmp1 = (mul_b[0] ? mul_a : 0) + ((mul_b[1] ? mul_a : 0) << 1);
	        sum_tmp2 = ((mul_b[2] ? mul_a : 0) << 2) + ((mul_b[3] ? mul_a : 0) << 3);
	    end
	end

	// Final product output
	reg [7:0] product_reg;
	always @(posedge clk or negedge rst_n) begin
	    if(!rst_n) begin
	        product_reg <= 'd0;
	    end else begin
	        product_reg <= sum_tmp1 + sum_tmp2;
	    end
	end

	// Assign final product to output
	assign mul_out = product_reg;
endmodule
